transform_func = '''
def transform(grid):
    h, w = len(grid), len(grid[0])
    center_r = center_c = None
    for r in range(h-1):
        for c in range(w-1):
            if (grid[r][c] == 2 and grid[r][c+1] == 2 and 
                grid[r+1][c] == 2 and grid[r+1][c+1] == 2):
                center_r, center_c = r, c
