    # Find nearest non-2 values in each quadrant
    tl_val = tr_val = bl_val = br_val = None

    # TL: r < center_r and c < center_c
    for r in range(center_r):
        for c in range(center_c):
            if grid[r][c] != 2:
                tl_val = (r, c, grid[r][c])
                break
    if tl_val: break

    # TR: r < center_r and c >= center_c+1
    for r in range(center_r):
        for c in range(center_c+1, w):
            if grid[r][c] != 2:
                tr_val = (r, c, grid[r][c])
                break
    if tr_val: break

    # BL: r >= center_r+1 and c < center_c
    for r in range(center_r+1, h):
        for c in range(center_c):
            if grid[r][c] != 2:
                bl_val = (r, c, grid[r][c])
                break
    if bl_val: break

    # BR: r >= center_r+1 and c >= center_c+1
    for r in range(center_r+1, h):
        for c in range(center_c+1, w):
            if grid[r][c] != 2:
                br_val = (r, c, grid[r][c])
                break

    output = [[0]*w for _ in range(h)]

    # Fill center block with 2s
    for r in [center_r, center_r+1]:
        for c in [center_c, center_c+1]:
            output[r][c] = 2

    # Main diagonal (r=c): BL above, TR below
    for r in range(h):
        if r in [center_r, center_r+1]:
            continue
        if r < center_r:
            output[r][r] = bl_val[2] if bl_val else 0
        else:
            output[r][r] = tr_val[2] if tr_val else 0

    # Anti-diagonal (r + c = constant): for h=8w=8, anti-diag=7
    for r in range(h):
        c = 7 - r
        if c < 0 or c >= w or r in [center_r, center_r+1]:
            continue
        if r < center_r:
            output[r][c] = tl_val[2] if tl_val else 0
        else:
            output[r][c] = br_val[2] if br_val else 0

    return output
